// The night bus window: rain sliding down fogged glass, each drop a tiny upside-down lens on
// the room, and the room graded to sodium streetlight: orange highs, teal-black shadows,
// brake-light reds kept red. The kick is the bus passing under a lamp.
// param[0] rain, param[1] sodium.
float aspect = resolution.x / resolution.y;
vec3 Y = vec3(0.299, 0.587, 0.114);
vec3 cam = source(uv);
vec2 p = vec2(uv.x * aspect, uv.y);

// Drops: columns that slide at their own speed; one drop per cell, or none.
float cs = mix(0.11, 0.05, param[0]);
float col = floor(p.x / cs);
float speed = 0.04 + 0.1 * hash(vec2(col, 2.0));
vec2 g = vec2(p.x / cs, p.y / cs + time * speed / cs);
vec2 id = floor(g);
vec2 f = fract(g) - 0.5;
vec2 centre = vec2((hash(id) - 0.5) * 0.5, (hash(id + vec2(3.0, 9.0)) - 0.5) * 0.4);
centre.x += sin(time * 2.0 + id.y) * 0.04;
float radius = 0.07 + 0.17 * hash(id + vec2(5.0, 1.0));
float has = step(hash(id + vec2(11.0, 4.0)), 0.15 + 0.5 * param[0]);
// A sliding drop is a little taller than wide.
vec2 dn = (f - centre) / radius * vec2(1.0, 0.8);
float inDrop = has * (1.0 - smoothstep(0.6, 1.0, length(dn)));

// The wet streak a drop leaves above it clears the fog.
float trail = has * step(centre.y, f.y) * (1.0 - smoothstep(0.0, radius * 0.5, abs(f.x - centre.x)));

// Fog: the glass softens the room outside the drops.
vec2 bl = vec2(1.0 / aspect, 1.0) * 0.011;
vec3 fog = (source(uv + bl) + source(uv - bl) + source(uv + vec2(bl.x, -bl.y)) + source(uv + vec2(-bl.x, bl.y))) * 0.25;
vec3 glass = mix(fog, cam, clamp(trail * 0.8, 0.0, 1.0));

// Inside a drop: the room seen sharp through a lens, upside down, with a dark rim and one
// small highlight at the top.
float dl = length(dn);
vec2 lens = uv - vec2(dn.x / aspect, dn.y) * radius * cs * 2.2;
vec3 drop = source(lens) * (1.1 - 0.35 * smoothstep(0.4, 1.0, dl));
vec2 hl = dn - vec2(-0.3, 0.45);
drop += palette[3] * exp(-dot(hl, hl) * 25.0) * 0.3;
glass = mix(glass, drop, inDrop);

// Sodium: shadows to night and teal, highs to orange and lamp, strong reds to brake light.
float l = dot(glass, Y);
vec3 dark = mix(palette[0], palette[1], smoothstep(0.0, 0.35, l));
vec3 lit = mix(palette[2], palette[3], smoothstep(0.6, 1.0, l));
vec3 graded = mix(dark, lit, smoothstep(0.2, 0.7, l));
float red = clamp(glass.r - max(glass.g, glass.b), 0.0, 1.0);
graded = mix(graded, palette[4] * (0.55 + l), smoothstep(0.28, 0.5, red));
graded = mix(glass, graded, param[1]);

// Passing streetlights: a soft band of lamp light slides across; the kick brightens it.
float sweep = fract(uv.x * 0.5 - time * 0.3) - 0.5;
float lamp = exp(-sweep * sweep * 18.0);
graded += palette[3] * lamp * (0.06 + 0.3 * audio.beat) * (0.3 + l);

return mix(cam, graded, strength);

// Light trails: what is bright streams sideways, as lights slide past a bus window, and fades.
// The hi-hats chop the trails into dashes: while the hats are loud the trail is dimmed hard
// seven and a half times a second, over a few frames rather than at once. param[0] trails.
vec3 now = source(uv);
vec2 drift = vec2(0.0035, 0.0006) * (0.5 + param[0]);
vec3 before = lastFrame(uv + drift);
float decay = mix(0.8, 0.965, param[0]);
float gate = 1.0 - 0.45 * audio.high * step(0.5, fract(time * 7.5));
// A max, never a sum: the feedback's gain stays below 1 and cannot build up.
vec3 streak = max(now, before * decay * gate);
return mix(now, streak, strength);
